import{_ as p,l as r,o as t,c as o,v as e,p as n,x as i,d as _,i as s,S as m}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"Discrete Flow Matching","description":"","frontmatter":{"title":"Discrete Flow Matching","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/discrete-flow-matching.md","filePath":"llm/discrete-flow-matching.md","lastUpdated":1789023840000}'),d={name:"llm/discrete-flow-matching.md"};function h(c,a,E,A,u,B){const l=r("Mermaid");return t(),o("div",null,[a[1]||(a[1]=e('<h1 id="discrete-flow-matching" tabindex="-1">Discrete Flow Matching <a class="header-anchor" href="#discrete-flow-matching" aria-label="Permalink to &quot;Discrete Flow Matching&quot;">​</a></h1><div class="epigraph"><p>生成概率速度在形式上与连续 Flow Matching 相同；路径与校正调度的调参会显著改变生成质量。</p><footer>—— Gat et al., Discrete Flow Matching, NeurIPS 2024</footer></div><p>连续 Flow Matching 用速度场把噪声推到数据。离散序列上，状态在有限词表 \\([d]^N\\) 上跳变。Gat、Remez、Shaul、Kreuk、Chen、Synnaeve、Adi 与 Lipman（Meta FAIR / Weizmann）在 Campbell 等离散流的 CTMC 框架上，给出更宽的概率路径族、任意源—目标耦合，以及用学到的后验（\\(x\\)-预测 / \\(\\epsilon\\)-预测）写成的统一概率速度。校正采样把正向与反向速度线性组合。\\(1.7\\)B 模型用 Llama-2 与 CodeLlama 的数据混合：HumanEval Pass@1 / @10 为 \\(6.7\\%/13.4\\%\\)，MBPP \\(1\\)-shot 为 \\(6.7\\%/20.6\\%\\)；条件文本生成的 Llama-3 \\(8\\)B 生成困惑度 \\(9.7\\)，同规模自回归 \\(22.3\\)。论文 arXiv:2407.15595，NeurIPS 2024。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把离散数据嵌进连续空间再扩散，或在离散状态上做 D3PM / 离散流，都还没在代码与开放生成上把差距收到可部署。需要一条路径：源分布 \\(p\\)（常为全 MASK，或均匀）走到数据 \\(q\\)，中间 \\(p_t\\) 可采样，速度可用神经网络学的后验表示，并且调度 \\(\\kappa_t\\) 可调。</p><p>连续 FM 的欧拉步是 \\(X_{t+h}=X_t+h u_t(X_t)\\)。离散类比是每个位置独立抽 \\(X^i_{t+h}\\sim \\delta_{X^i_t}+h u^i_t(\\cdot,X_t)\\)，速度满足列和为零、非对角非负。若该速度生成 \\(p_t\\)，则一小步后的分布是 \\(p_{t+h}+o(h)\\)。问题化为：对给定的凸组合路径，闭式写出 \\(u_t\\)。</p><h3 id="耦合与调度不是装饰" tabindex="-1">耦合与调度不是装饰 <a class="header-anchor" href="#耦合与调度不是装饰" aria-label="Permalink to &quot;耦合与调度不是装饰&quot;">​</a></h3><p>无条件耦合：源为全掩码，目标为数据，独立。条件耦合：按随机掩码把目标的一部分露出来当 \\(X_0\\)，改善条件采样与填空。调度 \\(\\kappa_t\\) 可以是简单凸插值 \\((1-\\kappa_t)\\delta_{x_0}+\\kappa_t\\delta_{x_1}\\)，也可以再混均匀噪声。原文强调路径与校正器调度对生成困惑度的影响大于再堆一种网络变体。\\(\\kappa_t=t\\) 回到 Campbell 等 2024；其他形状会明显更好。</p><p><span class="marginnote">「概率速度」不是完整状态空间 \\(D\\times D\\) 上的速率矩阵：每个位置的 \\(u^i\\) 会在 \\(z\\to z\\) 上贡献多条自环。作者故意不用 rate matrix 这个词，以免与 CTMC 教科书对象混淆。实现时按位置更新即可，不要物化 \\(|D|^2\\) 的矩阵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>条件路径 \\(p_t(x^i\\mid x_0,x_1)=\\sum_j \\kappa^{i,j}_t w^j(x^i\\mid x_0,x_1)\\)，权重非负且求和为 \\(1\\)。边际路径对耦合 \\(\\pi(x_0,x_1)\\) 积分。条件速度有闭式；边际速度是条件速度按后验 \\(p_t(x_0,x_1\\mid z)\\) 的期望。对凸插值路径，正向速度化为</p> \\[u^i_t(x^i,z)=\\frac{\\dot\\kappa_t}{1-\\kappa_t}\\big(p_{1\\mid t}(x^i\\mid z)-\\delta_z(x^i)\\big), \\]<p>与连续 FM 的 \\(x\\)-预测形式相同。反向时间用噪声预测 \\(p_{0\\mid t}\\)。训练最小化后验的交叉熵：对去噪器即 \\(\\mathbb{E}[-\\sum_i\\log p_{1\\mid t}(X^i_1\\mid X_t)]\\)。最优即定理中的 \\(w^j\\) 后验。</p><h3 id="校正采样与校正迭代" tabindex="-1">校正采样与校正迭代 <a class="header-anchor" href="#校正采样与校正迭代" aria-label="Permalink to &quot;校正采样与校正迭代&quot;">​</a></h3><p>\\(\\bar u_t=\\alpha_t\\hat u_t-\\beta_t\\check u_t\\)。若 \\(\\alpha_t-\\beta_t=1\\)，仍生成 \\(p_t\\)，但每步相当于多走一点再退一点，把噪声重新引入，即校正采样。若 \\(\\alpha_t-\\beta_t=0\\)，在固定 \\(t\\) 上重复采样，收敛到 \\(p_t\\)，即校正迭代。独立耦合且源 i.i.d. 时，反向速度可简化为不估计 \\(p_{0\\mid t}\\)，只用已知源 \\(p(x^i)\\)。这把 Song / Campbell 的校正与随机采样收进同一组系数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无条件生成（无温度、无校正）表：FM 凸插值路径在 \\(1024\\) NFE 下 Llama-2 生成困惑度 \\(22.5\\)，混均匀噪声的路径 \\(22.3\\)，对照 Lou 等 SEDD \\(27.2\\)、Campbell 等 \\(28.7\\)、自回归 \\(31.4\\)（该表设定）。条件生成 \\(1.7\\)B：C-coupling 在 \\(512\\) NFE 下 Llama-3 困惑度 \\(9.7\\)，U-coupling \\(10.3\\)，同规模 AR \\(22.3\\)，Llama-2 \\(7\\)B 参考 \\(8.3\\)。代码数字见摘要；图 1 展示左到右提示与中间填空。调度调对之后，离散流与自回归的生成差距明显收窄，但 HumanEval 绝对数字仍远低于专用代码 LLM。</p><p>连续性方程用离散散度写出概率通量，证明「速度生成路径」与连续情况平行。这是形式统一的来源，不是说实现可以复用连续 FM 的 ODE 求解器：离散一步是分类采样，不是加向量。</p><p><span class="marginnote">生成困惑度用外部 LM（Llama-2/3、GPT-2）评无条件或条件样本，低更好，但会偏爱与裁判同族的语言。熵列用来防止「重复套话把困惑度打低」。不要只报困惑度不报熵。代码 Pass@k 是另一套分布，不能用 \\(9.7\\) 生成困惑度去推断 HumanEval。</span></p><h3 id="与掩码扩散的关系" tabindex="-1">与掩码扩散的关系 <a class="header-anchor" href="#与掩码扩散的关系" aria-label="Permalink to &quot;与掩码扩散的关系&quot;">​</a></h3><p>全 MASK 源 + 凸插值路径，看起来像吸收扩散。Flow Matching 的时间是插值调度，速度用后验闭式，校正器是一等组件；D3PM/SEDD/MDLM 从前向速率矩阵与 ELBO 出发。离散 FM 可以混均匀噪声、任意耦合，不限于 MASK。不要把 \\(p_{1\\mid t}\\) 直接叫作 MDLM 的 \\(x_\\theta\\)：训练损失与采样 ODE/CTMC 步都不同，尽管都可以非自回归揭 token。</p>',21)),(t(),n(m,null,{default:i(()=>[s(l,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20X0%5B%22%E6%BA%90%20X0%20MASK%20%E6%88%96%E6%9D%A1%E4%BB%B6%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20PATH%5B%22%E8%B0%83%E5%BA%A6%20%CE%BA_t%20%E5%AE%9A%E4%B9%89%20p_t%22%5D%0A%20%20X1%5B%22%E7%9B%AE%E6%A0%87%20X1%20%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20PATH%0A%20%20PATH%20--%3E%20POST%5B%22%E5%AD%A6%E4%B9%A0%E5%90%8E%E9%AA%8C%20p1%7Ct%22%5D%0A%20%20POST%20--%3E%20U%5B%22%E6%A6%82%E7%8E%87%E9%80%9F%E5%BA%A6%20u_t%22%5D%0A%20%20U%20--%3E%20STEP%5B%22%E4%BD%8D%E7%BD%AE%E7%8B%AC%E7%AB%8B%E5%88%86%E7%B1%BB%E4%B8%80%E6%AD%A5%22%5D%0A%20%20C%5B%22%E6%A0%A1%E6%AD%A3%20%CE%B1%2C%CE%B2%22%5D%20--%3E%20U%0A%20%20STEP%20--%3E%20Y%5B%22X1%20%E6%A0%B7%E6%9C%AC%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[_(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>\\(1.7\\)B 与 Llama-2 \\(7\\)B 的生成困惑度接近，不等于通用能力接近；HumanEval \\(6.7\\%\\) Pass@1 说明代码仍弱。NFE \\(256\\)–\\(1024\\) 与自回归 \\(1024\\) token 的计算结构不同。双精度采样表与主表数字不同，复现要声明精度。路径族很宽，调度是真超参，默认真值插值会留下质量。</p><p>闭源数据混合（Llama-2 / CodeLlama 配比）使精确复现训练不可审计。理论贡献（路径、速度、校正）与 \\(1.7\\)B 结果应分开引用。不要把连续 Lipman 等 2022 的图像 FM 实验写进本篇表格。</p><p>反向采样 \\(X_{t-h}\\sim\\delta-h u_t\\) 要求 \\(-u\\) 仍是合法速度，用于从数据附近走回噪声或做校正。独立 MASK 源时反向不必学 \\(p_{0\\mid t}\\)，实现更省。训练时 \\(t\\) 通常均匀抽，\\(X_t\\) 从条件路径抽样，损失只看被预测的后验类别，形状像带噪声条件的非自回归交叉熵，但梯度对应的是生成速度，不是 D3PM 的完整 KL。若调度 \\(\\kappa_t\\) 在 \\(t\\to 1\\) 过陡，去噪器前期几乎看不到数据信号；过平则后期仍大量 MASK。原文把调度与校正器写成「关键超参」，复现应先扫 \\(\\kappa\\)，而不是先换宽度。代码填空例子说明条件耦合把已写好的签名钉在 \\(X_0\\)，模型只填函数体，这是产品接口，不是自回归 infill 微调。</p><p><span class="marginnote">出处：Gat, Remez, Shaul, Kreuk, Chen, Synnaeve, Adi, Lipman，<em>Discrete Flow Matching</em>，NeurIPS 2024（arXiv:2407.15595）。离散 CTMC 流引用 Campbell et al. 2024；连续对照 Lipman et al. 2022。Meta 研究页有同期介绍。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Discrete Flow Matching 用可调度的离散概率路径与后验参数化的概率速度，形式与连续 FM 对齐。</li><li>任意耦合、校正采样/迭代是一等组件；调度对生成质量很敏感。</li><li>\\(1.7\\)B 在条件生成困惑度上大幅好于同规模 AR，代码 Pass@k 展示非自回归填空，但绝对水平有限。</li><li>生成困惑度依赖裁判模型，须同时看熵；不要与吸收扩散的 NELBO 表混比。</li><li>实现按位置跳变，不要展开全状态速率矩阵。</li><li>出处：Gat et al.，NeurIPS 2024（arXiv:2407.15595）。</li></ul>',7))])}const P=p(d,[["render",h]]);export{D as __pageData,P as default};
